<?php
require __DIR__.'/api/auth.php';
$token=(string)($_GET['token']??$_POST['token']??'');$hash=hash('sha256',$token);$s=db()->prepare('SELECT * FROM registrations WHERE activation_token_hash=? AND activation_expires_at>NOW() AND user_id IS NULL');$s->execute([$hash]);$reg=$s->fetch();$error='';$existing=null;
if($reg){$s=db()->prepare('SELECT id FROM users WHERE email=? AND active=1');$s->execute([$reg['email']]);$existing=$s->fetchColumn();$current=current_user();if($existing&&$current&&(int)$current['id']===(int)$existing){db()->prepare('UPDATE registrations SET user_id=?,activation_token_hash=NULL,activation_expires_at=NULL WHERE id=?')->execute([$existing,$reg['id']]);header('Location: /dashboard.php');exit;}}
if($_SERVER['REQUEST_METHOD']==='POST'&&$reg&&!$existing){check_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9._-]{3,40}$/',$username))$error='Username: 3–40 letters, numbers, dots, dashes or underscores.';elseif(strlen($password)<8)$error='Password must contain at least 8 characters.';else{try{db()->beginTransaction();$q=db()->prepare("INSERT INTO users(username,email,password_hash,role,registration_id) VALUES(?,?,?,'user',?)");$q->execute([$username,$reg['email'],password_hash($password,PASSWORD_DEFAULT),$reg['id']]);$uid=(int)db()->lastInsertId();db()->prepare('UPDATE registrations SET user_id=?,activation_token_hash=NULL,activation_expires_at=NULL WHERE id=?')->execute([$uid,$reg['id']]);db()->commit();session_regenerate_id(true);$_SESSION['user_id']=$uid;header('Location: /dashboard.php');exit;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='This username is already in use.';}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Create account — SPECTECHNOLOGY</title><link rel="stylesheet" href="/assets/site-prod.css?v=20260915"><link rel="stylesheet" href="/assets/portal.css?v=20260915-2"></head><body class="portal"><main class="auth-card"><a href="/" class="portal-logo"><img src="/noBgColor-dark.png" alt="SPECTECHNOLOGY"></a><?php if(!$reg):?><h1>Link expired or already used</h1><p>Ask SPECTECHNOLOGY for a new invitation.</p><?php elseif($existing):?><p class="eyebrow">EXISTING ACCOUNT</p><h1>This email already has an account</h1><p>Sign in to add application #<?=e((string)$reg['id'])?> and its files to your dashboard.</p><a class="primary" href="/login.php?token=<?=rawurlencode($token)?>">Sign in / Zaloguj się</a><?php else:?><p class="eyebrow">CREATE YOUR PORTAL ACCOUNT</p><h1>Create account / Utwórz konto</h1><p><?=e($reg['email'])?></p><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>Username / Login<input name="username" required minlength="3" maxlength="40"></label><label>Password / Hasło<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><button class="primary">Create account / Utwórz konto</button></form><?php endif?><a href="/">← Main page / Strona główna</a></main></body></html>